PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE stories (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, cover TEXT, content TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, audio_triggers TEXT NOT NULL DEFAULT '[]');
CREATE TABLE story_resources (id INTEGER PRIMARY KEY AUTOINCREMENT, story_id INTEGER NOT NULL, page INTEGER NOT NULL, word TEXT NOT NULL, audio_url TEXT NOT NULL, FOREIGN KEY (story_id) REFERENCES stories(id) ON DELETE CASCADE);
CREATE INDEX idx_story_resources_story_page ON story_resources(story_id, page);
DELETE FROM sqlite_sequence;
